// Clean-room generalized vector First Fit bin-packing profile.
#include <array>
#include <cstddef>
#include <cstdint>
namespace{constexpr std::size_t N=32,D=4,INPUT=130,FIELDS=161;void put(std::uint8_t*out,std::size_t at,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t i=0;i<8;++i){out[at+i]=static_cast<std::uint8_t>(b&255u);b>>=8;}}}
extern "C" std::int64_t vector_bin_packing(const std::int64_t*input,std::size_t length,std::uint8_t*output,std::size_t capacity){if(!input||length<2||length>INPUT)return -1;auto nn=input[0],dd=input[1];if(nn<1||nn>32||dd<1||dd>4||length!=2+static_cast<std::size_t>(nn*dd))return -1;auto n=static_cast<std::size_t>(nn),d=static_cast<std::size_t>(dd);for(std::size_t i=0;i<n*d;++i)if(input[2+i]<0||input[2+i]>1000)return -1;std::array<std::array<std::int64_t,D>,N> load{};std::array<std::size_t,N> assignment{};std::size_t bins=0;for(std::size_t item=0;item<n;++item){auto chosen=bins;for(std::size_t b=0;b<bins;++b){bool fits=true;for(std::size_t q=0;q<d;++q)if(load[b][q]+input[2+item*d+q]>1000)fits=false;if(fits){chosen=b;break;}}if(chosen==bins)++bins;assignment[item]=chosen;for(std::size_t q=0;q<d;++q)load[chosen][q]+=input[2+item*d+q];}std::array<std::int64_t,FIELDS> staged{};std::size_t count=0;staged[count++]=static_cast<std::int64_t>(bins);for(std::size_t i=0;i<n;++i)staged[count++]=static_cast<std::int64_t>(assignment[i]);for(std::size_t b=0;b<bins;++b)for(std::size_t q=0;q<d;++q)staged[count++]=load[b][q];if(!output||capacity<8*count)return -2;for(std::size_t i=0;i<count;++i)put(output,8*i,staged[i]);return static_cast<std::int64_t>(8*count);}
